function getSkillKey(job, skill) {
  return `${job}:${skill.id || `passive-${skill.level}`}`;
}

function getSkillUpgradeLevel(progress, job, skill) {
  return Math.max(1, Math.min(SkillUpgradePolicy.MAX_SKILL_LEVEL, Number(progress?.skillLevels?.[getSkillKey(job, skill)]) || 1));
}

function getSkillEffect(progress, job, skill) {
  return ClassSkillPolicy.getEffect(job, skill.id, getSkillUpgradeLevel(progress, job, skill))
    || WarriorAdvancementPolicy.getEffect(skill.id, getSkillUpgradeLevel(progress, job, skill))
    || RogueAdvancementPolicy.getEffect(skill.id, getSkillUpgradeLevel(progress, job, skill))
    || HunterAdvancementPolicy.getEffect(skill.id, getSkillUpgradeLevel(progress, job, skill))
    || MageAdvancementPolicy.getEffect(skill.id, getSkillUpgradeLevel(progress, job, skill))
    || PriestAdvancementPolicy.getEffect(skill.id, getSkillUpgradeLevel(progress, job, skill)) || {};
}

function getHunterInstinctEffect(progress = getProgress()) {
  const definition = ClassSkillPolicy.getSkill('hunter', 'hunting-instinct');
  return ClassSkillPolicy.getEffect('hunter', 'hunting-instinct', getSkillUpgradeLevel(progress, 'hunter', definition));
}

function getKnownSkills(job, level, progress = getProgress()) {
  const base = skillProgression[job] || [];
  if (!progress?.advancedClass) return base;
  if (job === 'warrior') return [...base, ...WarriorAdvancementPolicy.getSkills(progress.advancedClass)];
  if (job === 'assassin') return [...base, ...RogueAdvancementPolicy.getSkills(progress.advancedClass)];
  if (job === 'hunter') return [...base, ...HunterAdvancementPolicy.getSkills(progress.advancedClass)];
  if (job === 'mage') return [...base, ...MageAdvancementPolicy.getSkills(progress.advancedClass)];
  if (job === 'priest') return [...base, ...PriestAdvancementPolicy.getSkills(progress.advancedClass)];
  return base;
}

function getSkillManaCost(skill) {
  if (skill.id === 'heal') return 28;
  if (skill.targets && skill.targets > 1) return 26;
  if (skill.id === 'companion') return 24;
  return 18;
}

function getSkillResourceCost(job, skill) {
  const priestSkill = PriestAdvancementPolicy.getSkill(skill?.id);
  if (priestSkill) return priestSkill.manaCost;
  const rogueSkill = RogueAdvancementPolicy.getSkill(skill?.id);
  if (rogueSkill) return rogueSkill.energyCost || 0;
  if (WarriorAdvancementPolicy.getSkill(skill?.id)) return 0;
  if (HunterArrowPolicy.isHunter(job)) {
    return HunterArrowPolicy.getSkillCost(skill.id) ?? 0;
  }
  if (AssassinEnergyPolicy.isAssassin(job)) {
    return AssassinEnergyPolicy.getSkillCost(skill.id) ?? getSkillManaCost(skill);
  }
  return getSkillManaCost(skill);
}

function usesManaResource(job) {
  return !WarriorResourcePolicy.isWarrior(job)
    && !AssassinEnergyPolicy.isAssassin(job)
    && !HunterArrowPolicy.isHunter(job);
}

function getPlayerAttackProfile(character, skill = null) {
  if (skill?.id === 'companion') return { damageType: 'physical', attackRange: 'melee' };
  const magicJob = character.job === 'mage' || character.job === 'priest';
  const meleeJob = character.job === 'warrior' || character.job === 'assassin';
  return {
    damageType: magicJob ? 'magic' : 'physical',
    attackRange: meleeJob ? 'melee' : 'ranged',
    element: character.job === 'mage' ? ({ fireball: 'fire', blizzard: 'ice', 'chain-lightning': 'lightning', 'arcane-missile': 'arcane', 'arcane-torrent': 'arcane' }[skill?.id] || '') : ''
  };
}

function applyDot(index, type, damage, duration, maxStacks = 1, options = {}) {
  if (battle.enemyHps[index] <= 0) return false;
  const dots = battle.enemyDots[index] || [];
  const dotGroup = options.dotGroup || '';
  const sameType = dots.filter((dot) => dot.type === type && (dot.dotGroup || '') === dotGroup);
  if (options.refreshAllSameType) sameType.forEach((dot) => {
    dot.remaining = duration;
    dot.extendedSeconds = 0;
    dot.toxicBloodBonusTickUsed = false;
    if (options.durationMs) dot.expiresAt = (options.now || Date.now()) + options.durationMs;
    if (options.tickIntervalMs) {
      dot.tickIntervalMs = options.tickIntervalMs;
      dot.nextTickAt = (options.now || Date.now()) + options.tickIntervalMs;
    }
  });
  const existing = sameType.length >= maxStacks ? sameType.sort((a, b) => a.remaining - b.remaining)[0] : null;
  if (existing) {
    if (options.replaceOnlyIfStronger && damage < existing.damage) return false;
    if (!options.refreshOnly) existing.damage = Math.max(existing.damage, damage);
    existing.remaining = options.refreshDuration ? duration : Math.max(existing.remaining, duration);
    if (options.refreshDuration) { existing.extendedSeconds = 0; existing.toxicBloodBonusTickUsed = false; }
    if (options.durationMs) existing.expiresAt = (options.now || Date.now()) + options.durationMs;
    existing.defenseReduction = Math.max(existing.defenseReduction || 0, options.defenseReduction || 0);
    if (options.tickIntervalMs) {
      existing.tickIntervalMs = options.tickIntervalMs;
      existing.nextTickAt = (options.now || Date.now()) + options.tickIntervalMs;
    }
    if (options.source) {
      const telemetry = CombatCorePolicy.telemetry(options.source);
      telemetry.dotRefreshes[type] = (telemetry.dotRefreshes[type] || 0) + 1;
      CombatCorePolicy.recordEvent(options.source, 'dotEvents', { atMs: options.now || Date.now(), type, action: 'refresh', targetIndex: index, stacks: sameType.length, remaining: existing.remaining, nextTickAt: existing.nextTickAt });
    }
    return false;
  }
  dots.push({ type, damage, remaining: duration, source: options.source || null, defenseReduction: options.defenseReduction || 0, tickIntervalMs: options.tickIntervalMs || 0, nextTickAt: options.tickIntervalMs ? (options.now || Date.now()) + options.tickIntervalMs : 0, expiresAt: options.durationMs ? (options.now || Date.now()) + options.durationMs : 0, dotGroup });
  battle.enemyDots[index] = dots;
  if (options.source) {
    const telemetry = CombatCorePolicy.telemetry(options.source), stacks = dots.filter((dot) => dot.type === type).length;
    telemetry.dotApplications[type] = (telemetry.dotApplications[type] || 0) + 1;
    telemetry.maxDotStacks[type] = Math.max(telemetry.maxDotStacks[type] || 0, stacks);
    CombatCorePolicy.recordEvent(options.source, 'dotEvents', { atMs: options.now || Date.now(), type, action: 'apply', targetIndex: index, stacks, remaining: duration, nextTickAt: options.tickIntervalMs ? (options.now || Date.now()) + options.tickIntervalMs : 0 });
  }
  return true;
}

function applyRogueDotEntryDamage(index, member, type, tickDamage, ratio = .5, now = Date.now()) {
  if (!member || battle.enemyHps[index] <= 0) return 0;
  let multiplier = 1 + RogueAdvancementPolicy.getBloodDotDamageBonus(member, battle.enemyDots[index], type, { includeFullBlood: false });
  multiplier += RogueAdvancementPolicy.getTargetBonuses(member, battle.enemyDots[index], getEnemySkillState(index), battle.enemyHps[index] / getEnemyDefinition(index).maxHp, 'dot', now).dotDamage;
  return applyDamageToMonster(index, tickDamage * ratio * multiplier, { damageType: 'periodic', attackRange: 'none' }, { attacker: member, attackKind: `${type}-entry`, canEvade: false, canParry: false, effectType: 'dot' }).finalDamage;
}

function applyRoguePoison(index, member, damage, duration, maxStacks, options = {}) {
  if (RogueAdvancementPolicy.isAdvanced(member?.progress, 'venom')) maxStacks = Math.max(maxStacks, RogueAdvancementPolicy.getPoisonMaxStacks(member));
  const before = RogueAdvancementPolicy.poisonStacks(battle.enemyDots[index]);
  applyDot(index, 'poison', damage, duration, maxStacks, options);
  const added = Math.max(0, RogueAdvancementPolicy.poisonStacks(battle.enemyDots[index]) - before);
  if (added && RogueAdvancementPolicy.isAdvanced(member?.progress, 'venom')) applyRogueDotEntryDamage(index, member, 'poison', damage * added, RogueAdvancementPolicy.POISON_ENTRY_RATIO, options.now || Date.now());
  return added;
}

