function getRuneOutgoingMultiplier(member, targetIndex) {
  let multiplier = RunePolicy.hasWord(member.progress.equipment, 'battle-will') && member.currentHp / member.maxHp > .70 ? 1.08 : 1;
  if (RunePolicy.hasWord(member.progress.equipment, 'conquest')) {
    if (member.runeConquestTarget !== targetIndex) { member.runeConquestTarget = targetIndex; member.runeConquestStacks = 0; }
    member.runeConquestStacks = Math.min(5, (member.runeConquestStacks || 0) + 1);
    multiplier *= 1 + member.runeConquestStacks * .02;
  }
  return multiplier;
}

function triggerRuneFrenzy(member, critical, now) {
  if (critical && RunePolicy.hasWord(member.progress.equipment, 'frenzy')) member.runeFrenzyUntil = now + 3000;
}

function tryApplyThornCorrosion(member, targetIndex, attackKind, finalDamage, now = Date.now()) {
  const corrosion = ChapterTwoSpecialEquipmentPolicy.rollThornCorrosion(member.progress.equipment, { attackKind, finalDamage, totalAttack: member.stats.attack });
  if (!corrosion || battle.enemyHps[targetIndex] <= 0) return false;
  applyDot(targetIndex, 'thorn-corrosion', corrosion.tickDamage, corrosion.tickCount, 1, {
    source: member,
    tickIntervalMs: corrosion.tickIntervalMs,
    now,
    refreshOnly: true,
    refreshDuration: true
  });
  logBattle(`◆ ${member.name}對【${getEnemyDefinition(targetIndex).name}】觸發【荊棘侵蝕】，每秒造成 ${corrosion.tickDamage} 傷害，持續 5 秒。`, 'system');
  return true;
}

function getMageSkillElement(skillId, stormElement = '') {
  return stormElement || ({ fireball: 'fire', blizzard: 'ice', 'chain-lightning': 'lightning' }[skillId] || '');
}

function applyElementalStormStatus(index, element, member, damage, now) {
  const state = getEnemySkillState(index);
  if (element === 'fire') {
    const shockSnapshot = getMageShockState(index,member)?.until > now ? 1.5 : 1;
    applyDot(index, 'burn', Math.max(1, Math.ceil(damage / shockSnapshot * .18 * member.stats.dotMultiplier)), 4, 1, { source: member });
    state.visualBurnAt = now + 500;
  } else if (element === 'ice') {
    state.slowedUntil = Math.max(state.slowedUntil, now + 4000);
    state.visualSlowAt = now + 500;
  } else if (element === 'lightning') {
    state.paralyzedUntil = now + 4000;
    state.visualParalyzedAt = now + 500;
  }
}

function resolveFinishedMageResonance(member, now) {
  const release = MageAdvancementPolicy.finishResonance(member, now);
  if (!release) return;
  const targets = aliveEnemyIndexesByAge().slice(0, release.targets || 1);
  if (!targets.length) return;
  let totalDamage = 0;
  for (const targetIndex of targets) {
    const result = applyDamageToMonster(targetIndex, member.stats.attack * release.power, { damageType: 'magic', attackRange: 'ranged', element: release.element }, { attacker: member, attackKind: 'resonance', sourceSkill:'resonance-overload', canParry: false });
    totalDamage += result.finalDamage;
  }
  MageAdvancementPolicy.recordOverloadDamage(member, totalDamage, targets.length);
}

function queueClassHealAfterglow(member, healTarget, event) {
  const farmingIdentity=typeof getPermanentPartyRuntime==='function'&&getPermanentPartyRuntime()?.coordinator?{mainId:getPermanentPartyRuntime().mainId,battle}:null;
  setTimeout(() => {
    if(farmingIdentity&&(farmingIdentity.mainId!==getPermanentPartyRuntime()?.mainId||farmingIdentity.battle!==battle))return;
    const pending = member.pendingClassHeals || [];
    const index = pending.findIndex(entry => entry.id === event.id);
    if (index < 0) return;
    if (offlinePartyPreviewPausedAt !== null) return;
    if (Date.now() < event.dueAt) { queueClassHealAfterglow(member, healTarget, event); return; }
    pending.splice(index, 1);
    if (!healTarget.alive) return;
    if (member.job === 'priest') PriestAdvancementPolicy.heal(member, healTarget, event.amount, 'afterglow');
    else healTarget.currentHp = Math.min(healTarget.maxHp, healTarget.currentHp + event.amount);
    if (fighting) updateBattleUI();
  }, Math.max(0, event.dueAt - Date.now()));
}

function scheduleClassHealAfterglow(member, healTarget, amount, now = Date.now()) {
  member.classHealSequence = (Number(member.classHealSequence) || 0) + 1;
  const event = { id: member.classHealSequence,
    dueAt: now + 3000, targetId: healTarget.id, amount };
  member.pendingClassHeals = member.pendingClassHeals || [];
  member.pendingClassHeals.push(event);
  queueClassHealAfterglow(member, healTarget, event);
}

